// Quote signatures, v2: the network byte after the domain. Our own vector here; the dealer's shared vector
// (tests/fixtures/quote-sig.json, regenerated by the keeper and dealer piece) once it carries a v2 signature.
import { readFileSync } from "node:fs";
import { address, createKeyPairFromPrivateKeyBytes, getAddressFromPublicKey, signBytes } from "@solana/kit";
import { describe, expect, it } from "vitest";
import { QUOTE_MESSAGE_LEN, quoteMessage, verifyQuote, type SignedTerms } from "../src/keeler/quote-sig";

const toHex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
const SOL = address("11111111111111111111111111111111");
const terms: SignedTerms = {
  network: "devnet",
  programId: address("F4hjig5RJbXW6vrgYaMcuWzR55kZF6tbKyf8c36nrtvU"),
  sellMint: address("So11111111111111111111111111111111111111112"),
  buyMint: SOL,
  trader: address("AKnL4NNf3DGWZJS6cPknBuEGnVsV4A4m5tgebLHaRSZ9"),
  sellAmount: 100_000_000n,
  buyAmount: 1_998_000n,
  expiry: 1_763_900_030n,
};

describe("quote message", () => {
  it("is 168 bytes: the v2 domain, the network byte, then the v1 fields in the v1 order", () => {
    const m = quoteMessage(terms);
    expect(m.length).toBe(QUOTE_MESSAGE_LEN);
    expect(new TextDecoder().decode(m.slice(0, 15))).toBe("keeler-quote-v2");
    expect(m[15]).toBe(1);
    expect(toHex(m.slice(16 + 64, 16 + 96))).toBe("00".repeat(32)); // SOL as the buy mint
    expect(new DataView(m.buffer).getBigUint64(16 + 128, true)).toBe(terms.sellAmount);
    expect(new DataView(m.buffer).getBigUint64(16 + 144, true)).toBe(terms.expiry);
    expect([quoteMessage({ ...terms, network: "local" })[15], quoteMessage({ ...terms, network: "mainnet" })[15]]).toEqual([0, 2]);
  });
  it("refuses values outside u64 and unknown networks", () => {
    expect(() => quoteMessage({ ...terms, buyAmount: 1n << 64n })).toThrow(RangeError);
    for (const network of ["testnet", "toString", ""]) expect(() => quoteMessage({ ...terms, network })).toThrow(RangeError);
  });
});

describe("verifyQuote", async () => {
  const keys = await createKeyPairFromPrivateKeyBytes(new Uint8Array(32).fill(9));
  const dealer = await getAddressFromPublicKey(keys.publicKey);
  const sig = toHex(await signBytes(keys.privateKey, quoteMessage(terms)));

  it("accepts the dealer's signature over these terms on this network", async () => {
    expect(await verifyQuote(dealer, sig, terms)).toBe(true);
  });
  it("rejects another network, other terms, another dealer, a flipped bit and a malformed field", async () => {
    expect(await verifyQuote(dealer, sig, { ...terms, network: "mainnet" })).toBe(false);
    expect(await verifyQuote(dealer, sig, { ...terms, buyAmount: terms.buyAmount + 1n })).toBe(false);
    expect(await verifyQuote(dealer, sig, { ...terms, trader: SOL })).toBe(false);
    expect(await verifyQuote(terms.trader, sig, terms)).toBe(false);
    expect(await verifyQuote(dealer, (sig[0] === "0" ? "1" : "0") + sig.slice(1), terms)).toBe(false);
    for (const bad of [undefined, 42, "", sig.slice(2), sig + "00", "zz".repeat(64)]) {
      expect(await verifyQuote(dealer, bad, terms)).toBe(false);
    }
  });
  it("no longer accepts a v1 signature (no network byte)", async () => {
    const m = quoteMessage(terms);
    const v1 = Uint8Array.of(...new TextEncoder().encode("keeler-quote-v1"), ...m.slice(16));
    expect(v1.length).toBe(167);
    expect(await verifyQuote(dealer, toHex(await signBytes(keys.privateKey, v1)), terms)).toBe(false);
  });
});

const vector = JSON.parse(readFileSync(new URL("./fixtures/quote-sig.json", import.meta.url), "utf8"));
// The fixture is the dealer's; until it is regenerated for v2 it still holds a v1 signature, which v2 refuses.
const isV2 = typeof vector.message_hex === "string" && vector.message_hex.startsWith(toHex(new TextEncoder().encode("keeler-quote-v2")));
describe("the dealer's quote signature vector", () => {
  it.skipIf(!isV2)("verifies and reproduces the message", async () => {
    const i = vector.inputs;
    const t: SignedTerms = {
      network: i.network,
      programId: address(i.program_id),
      sellMint: address(i.sell_mint),
      buyMint: address(i.buy_mint),
      trader: address(i.trader),
      sellAmount: BigInt(i.sell_amount),
      buyAmount: BigInt(i.buy_amount),
      expiry: BigInt(i.expiry),
    };
    expect(toHex(quoteMessage(t))).toBe(vector.message_hex);
    expect(await verifyQuote(address(vector.pubkey), vector.signature_hex, t)).toBe(true);
    // The dealer's HTTP reply carries the same signature, as the Worker passes it through.
    expect(vector.http_reply.quote).toEqual({ buy_amount: i.buy_amount, expiry: i.expiry, signature: vector.signature_hex });
    expect(await verifyQuote(address(vector.pubkey), vector.signature_hex, { ...t, expiry: t.expiry + 1n })).toBe(false);
  });
});
